def classify(result):
    if not isinstance(result, dict):
        return 'error', '', dict()
    result.pop('header', None)
    try:
        sc = int(result.get('status_code') or 200)
    except Exception:
        sc = 200
    d = result.get('data')
    if isinstance(d, str):
        try:
            d = json.loads(d)
        except Exception:
            d = None
    if not isinstance(d, dict):
        return 'error', '', dict()
    r = d.get('result')
