        r = dict()
    rc = str(r.get('returnCode', r.get('code', '')))
    inner = d.get('data')
    if sc >= 400 or rc != '1' or not isinstance(inner, dict) or str(result.get('status', 'success')) not in ('success', ''):
        return 'error', rc, inner if isinstance(inner, dict) else dict()
    return 'ok', rc, inner
def set_out(result, what, say=''):
    o = dict()
    o['what_to_do_next'] = what
    if say:
        o['say_text'] = say
    if isinstance(result, dict):
        result['data'] = o

try:
    st, rc, d = classify(result)
    if st != 'ok':
        vars['email_state'] = 'error'
        vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim.'
        set_out(result, 'E-posta bilgisi alınamadı. Arayana yalnızca hesap kesim tarihi değişikliğini öner.')
    else:
        em = str(d.get('ibanEmail') or '').strip()
        if not em or str(d.get('communicationType')) == 'Phone':
            vars['email_state'] = 'no_email'
            vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim.'
        else:
