            vars['email_addr'] = em
            vars['offer_text'] = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
            local = em.split('@')[0]
            short = len(local) <= 20 and local.replace('_', '.').count('.') <= 1 and not any(ch.isdigit() or ch == '-' for ch in local)
            if short:
                sp = em
                sp = ' '.join(sp.split())
                vars['email_confirm_q'] = 'Ekstrenizi ' + sp + ' adresine göndermemi ister misiniz?'
            else:
